 x="78" y="126" fill="#1f4fd1" font-size="11" text-anchor="end" font-weight="bold">VBC</text><line x1="68" y1="204" x2="158" y2="204" stroke="#94a3b8" stroke-width="1.2" stroke-linecap="round"/><line x1="68" y1="150" x2="68" y2="204" stroke="#15803d" stroke-width="1.6" stroke-linecap="round"/><polygon points="64,158 72,158 68,150" fill="#15803d" stroke="#15803d" stroke-width="1"/><polygon points="64,196 72,196 68,204" fill="#15803d" stroke="#15803d" stroke-width="1"/><text x="62" y="182" fill="#15803d" font-size="11" text-anchor="end" font-weight="bold">VBE</text><text x="186" y="116" fill="#64748b" font-size="11">BC junction</text><text x="186" y="196" fill="#64748b" font-size="11">BE junction</text><line x1="268" y1="56" x2="268" y2="232" stroke="#cbd5e1" stroke-width="1" stroke-linecap="round"/><text x="282" y="72" fill="#64748b" font-size="11">region</text><text x="430" y="72" fill="#64748b" font-size="11" text-anchor="middle">VBE</text><text x="478" y="72" fill="#64748b" font-size="11" text-anchor="middle">VBC</text><line x1="280" y1="80" x2="508" y2="80" stroke="#94a3b8" stroke-width="1.2" stroke-linecap="round"/><text x="282" y="106" fill="#15803d" font-size="11" font-weight="bold">SATURATION</text><text x="282" y="121" fill="#64748b" font-size="11">VCE(sat) = 0.2V</text><text x="430" y="106" fill="#1d2943" font-size="11" text-anchor="middle">fwd</text><text x="478" y="106" fill="#1d2943" font-size="11" text-anchor="middle">fwd</text><text x="282" y="136" fill="#1f4fd1" font-size="11" font-weight="bold">ACTIVE</text><text x="282" y="151" fill="#64748b" font-size="11">IC = beta x IB</text><text x="430" y="136" fill="#1d2943" font-size="11" text-anchor="middle">fwd</text><text x="478" y="136" fill="#1d2943" font-size="11" text-anchor="middle">rev</text><text x="282" y="166" fill="#b91c1c" font-size="11" font-weight="bold">CUTOFF</text><text x="282" y="181" fill="#64748b" font-size="11">IC = 0</text><text x="430" y="166" fill="#1d2943" font-size="11" text-anchor="middle">rev</text><text x="478" y="166" fill="#1d2943" font-size="11" text-anchor="middle">rev</text><text x="282" y="196" fill="#b45309" font-size="11" font-weight="bold">REVERSE ACTIVE</text><text x="282" y="211" fill="#64748b" font-size="11">low gain, rare</text><text x="430" y="196" fill="#1d2943" font-size="11" text-anchor="middle">rev</text><text x="478" y="196" fill="#1d2943" font-size="11" text-anchor="middle">fwd</text><text x="10" y="272" fill="#1d2943" font-size="11">fwd = that junction conducts (about 0.7V on silicon). rev = it blocks.</text><text x="10" y="292" fill="#64748b" font-size="11">Saturation needs overdrive too: IB above IC/beta, not just VBE past 0.7V.</text></svg></div>$vsq$ as box) n
 where question like $q$%BJT 的四種工作區域%$q$;

-- q14：邏輯閘真值表
update public.interview_questions set
  answer = case when answer is not null and answer not like '%<svg%' then n.box || answer else answer end,
  answer_en = case when answer_en is not null and answer_en not like '%<svg%' then n.box || answer_en else answer_en end,
  answer_ja = case when answer_ja is not null and answer_ja not like '%<svg%' then n.box || answer_ja else answer_ja end,
  answer_ko = case when answer_ko is not null and answer_ko not like '%<svg%' then n.box || answer_ko else answer_ko end
  from (select $vsq$<div class="exam-diagram-box"><svg width="520" height="330" viewBox="0 0 520 330" xmlns="http://www.w3.org/2000/svg"><rect width="520" height="330" fill="#ffffff"/><text x="260" y="20" fill="#1d2943" font-size="13" text-anchor="middle" font-weight="bold">Truth table, and the gate that draws each column</text><text x="190" y="52" fill="#1d2943" font-size="11" text-anchor="middle" font-weight="bold">AND</text><g data-sym="gate"><path d="M 175 61 L 195 61 A 15 15 0 0 1 195 91 L 175 91 Z" fill="#fff" stroke="#1f4fd1" stroke-width="2"/><line x1="162" y1="69" x2="175" y2="69" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="162" y1="83" x2="175" y2="83" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="210" y1="76" x2="218" y2="76" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/></g><text x="260" y="52" fill="#1d2943" font-size="11" text-anchor="middle" font-weight="bold">OR</text><g data-sym="gate"><path d="M 244 61 Q 262 61 278 76 Q 262 91 244 91 Q 254 76 244 61 Z" fill="#fff" stroke="#1f4fd1" stroke-width="2"/><line x1="232" y1="69" x2="247" y2="69" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="232" y1="83" x2="247" y2="83" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="278" y1="76" x2="288" y2="76" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/></g><text x="330" y="52" fill="#1d2943" font-size="11" text-anchor="middle" font-weight="bold">NAND</text><g data-sym="gate"><path d="M 315 61 L 335 61 A 15 15 0 0 1 335 91 L 315 91 Z" fill="#fff" stroke="#1f4fd1" stroke-width="2"/><circle cx="354" cy="76" r="4" fill="#fff" stroke="#1f4fd1" stroke-width="2"/><line x1="302" y1="69" x2="315" y2="69" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="302" y1="83" x2="315" y2="83" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="358" y1="76" x2="358" y2="76" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/></g><text x="400" y="52" fill="#1d2943" font-size="11" text-anchor="middle" font-weight="bold">NOR</text><g data-sym="gate"><path d="M 384 61 Q 402 61 418 76 Q 402 91 384 91 Q 394 76 384 61 Z" fill="#fff" stroke="#1f4fd1" stroke-width="2"/><circle cx="422" cy="76" r="4" fill="#fff" stroke="#1f4fd1" stroke-width="2"/><line x1="372" y1="69" x2="387" y2="69" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="372" y1="83" x2="387" y2="83" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="426" y1="76" x2="428" y2="76" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/></g><text x="470" y="52" fill="#1d2943" font-size="11" text-anchor="middle" font-weight="bold">XOR</text><g data-sym="gate"><path d="M 454 61 Q 472 61 488 76 Q 472 91 454 91 Q 464 76 454 61 Z" fill="#fff" stroke="#1f4fd1" stroke-width="2"/><path d="M 448 61 Q 458 76 448 91" fill="none" stroke="#1f4fd1" stroke-width="2"/><line x1="442" y1="69" x2="457" y2="69" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="442" y1="83" x2="457" y2="83" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="488" y1="76" x2="498" y2="76" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/></g><text x="40" y="96" fill="#1d2943" font-size="11" text-anchor="middle" font-weight="bold">A</text><text x="90" y="96" fill="#1d2943" font-size="11" text-anchor="middle" font-weight="bold">B</text><line x1="20" y1="104" x2="500" y2="104" stroke="#94a3b8" stroke-width="1.2" stroke-linecap="round"/><line x1="120" y1="60" x2="120" y2="228" stroke="#94a3b8" stroke-width="1" stroke-linecap="round"/><text x="40" y="130" fill="#1d2943" font-size="11" text-anchor="middle">0</text><text x="90" y="130" fill="#1d2943" font-size="11" text-anchor="middle">0</text><text x="190" y="130" fill="#1d2943" font-size="11" text-anchor="middle">0</text><text x="260" y="130" fill="#1d2943" font-size="11" text-anchor="middle">0</text><text x="330" y="130" fill="#1d2943" font-size="11" text-anchor="middle">1</text><text x="400" y="130" fill="#1d2943" font-size="11" text-anchor="middle">1</text><text x="470" y="130" fill="#1d2943" font-size="11" text-anchor="middle">0</text><text x="40" y="158" fill="#1d2943" font-size="11" text-anchor="middle">0</text><text x="90" y="158" fill="#1d2943" font-size="11" text-anchor="middle">1</text><text x="190" y="158" fill="#1d2943" font-size="11" text-anchor="middle">0</text><text x="260" y="158" fill="#1d2943" font-size="11" text-anchor="middle">1</text><text x="330" y="158" fill="#1d2943" font-size="11" text-anchor="middle">1</text><text x="400" y="158" fill="#1d2943" font-size="11" text-anchor="middle">0</text><text x="470" y="158" fill="#1d2943" font-size="11" text-anchor="middle">1</text><text x="40" y="186" fill="#1d2943" font-size="11" text-anchor="middle">1</text><text x="90" y="186" fill="#1d2943" font-size="11" text-anchor="middle">0</text><text x="190" y="186" fill="#1d2943" font-size="11" text-anchor="middle">0</text><text x="260" y="186" fill="#1d2943" font-size="11" text-anchor="middle">1</text><text x="330" y="186" fill="#1d2943" font-size="11" text-anchor="middle">1</text><text x="400" y="186" fill="#1d2943" font-size="11" text-anchor="middle">0</text><text x="470" y="186" fill="#1d2943" font-size="11" text-anchor="middle">1</text><text x="40" y="214" fill="#1d2943" font-size="11" text-anchor="middle">1</text><text x="90" y="214" fill="#1d2943" font-size="11" text-anchor="middle">1</text><text x="190" y="214" fill="#1d2943" font-size="11" text-anchor="middle">1</text><text x="260" y="214" fill="#1d2943" font-size="11" text-anchor="middle">1</text><text x="330" y="214" fill="#1d2943" font-size="11" text-anchor="middle">0</text><text x="400" y="214" fill="#1d2943" font-size="11" text-anchor="middle">0</text><text x="470" y="214" fill="#1d2943" font-size="11" text-anchor="middle">0</text><text x="10" y="270" fill="#1d2943" font-size="11">NAND is the universal gate: wire enough of them and you get every other one.</text><text x="10" y="290" fill="#64748b" font-size="11">XOR is the disagreement detector - it outputs 1 only when the inputs differ.</text></svg></div>$vsq$ as box) n
 where question like $q$%請填寫以下邏輯閘的真值表%$q$;

-- q15：NMOS 反相器 + IN/OUT 波形
update public.interview_questions set
  answer = case when answer is not null and answer not like '%<svg%' then n.box || answer else answer end,
  answer_en = case when answer_en is not null and answer_en not like '%<svg%' then n.box || answer_en else answer_en end,
  answer_ja = case when answer_ja is not null and answer_ja not like '%<svg%' then n.box || answer_ja else answer_ja end,
  answer_ko = case when answer_ko is not null and answer_ko not like '%<svg%' then n.box || answer_ko else answer_ko end
  from (select $vsq$<div class="exam-diagram-box"><svg width="520" height="300" viewBox="0 0 520 300" xmlns="http://www.w3.org/2000/svg"><rect width="520" height="300" fill="#ffffff"/><text x="260" y="20" fill="#1d2943" font-size="13" text-anchor="middle" font-weight="bold">NMOS inverter: FET pulls down, resistor pulls up</text><g data-sym="rail"><line x1="146" y1="66" x2="146" y2="78" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="138" y1="66" x2="154" y2="66" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/></g><text x="156" y="72" fill="#b91c1c" font-size="11" font-weight="bold">5V</text><g data-sym="resistor"><line x1="146" y1="86" x2="146" y2="98" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><polyline points="146,98 139,101 153,107 139,113 153,119 146,122" fill="none" stroke="#1f4fd1" stroke-width="2" stroke-linejoin="round" stroke-linecap="round"/><line x1="146" y1="122" x2="146" y2="134" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/></g><text x="158" y="106" fill="#64748b" font-size="11">10k</text><line x1="146" y1="78" x2="146" y2="86" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="146" y1="134" x2="146" y2="150" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><g data-sym="junction"><circle cx="146" cy="150" r="2.6" fill="#1f4fd1"/></g><line x1="146" y1="150" x2="206" y2="150" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><text x="212" y="154" fill="#1d2943" font-size="11" font-weight="bold">OUT</text><g data-sym="nmos"><line x1="90" y1="190" x2="104" y2="190" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="104" y1="178" x2="104" y2="202" stroke="#1f4fd1" stroke-width="2.6" stroke-linecap="round"/><line x1="111" y1="177" x2="111" y2="203" stroke="#1f4fd1" stroke-width="2.6" stroke-linecap="round"/><line x1="111" y1="182" x2="124" y2="182" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="124" y1="182" x2="124" y2="170" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="124" y1="170" x2="146" y2="170" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="111" y1="198" x2="124" y2="198" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="124" y1="198" x2="124" y2="210" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="124" y1="210" x2="146" y2="210" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="111" y1="190" x2="124" y2="190" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><polygon points="117,186 117,194 111,190" fill="#1f4fd1" stroke="#1f4fd1" stroke-width="1"/><line x1="124" y1="190" x2="124" y2="198" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="138" y1="210" x2="138" y2="196" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><polygon points="132,196 144,196 138,184" fill="none" stroke="#1f4fd1" stroke-width="2"/><line x1="132" y1="184" x2="144" y2="184" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="138" y1="184" x2="138" y2="170" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/></g><line x1="146" y1="170" x2="146" y2="150" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="146" y1="210" x2="146" y2="230" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><g data-sym="ground"><line x1="146" y1="230" x2="146" y2="244" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="134" y1="244" x2="158" y2="244" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="138" y1="249" x2="154" y2="249" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><line x1="142" y1="254" x2="150" y2="254" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/></g><line x1="90" y1="190" x2="40" y2="190" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><text x="34" y="194" fill="#1d2943" font-size="11" text-anchor="end" font-weight="bold">IN</text><text x="276" y="92" fill="#b45309" font-size="11" text-anchor="end" font-weight="bold">IN</text><polyline points="284,100 320,100 320,74 374,74 374,100 428,100 428,74 494,74" fill="none" stroke="#b45309" stroke-width="2" stroke-linejoin="round" stroke-linecap="round"/><text x="276" y="172" fill="#1f4fd1" font-size="11" text-anchor="end" font-weight="bold">OUT</text><polyline points="284,154 320,154 320,180 374,180 386,154 428,154 428,180 494,180" fill="none" stroke="#1f4fd1" stroke-width="2" stroke-linejoin="round" stroke-linecap="round"/><text x="392" y="140" fill="#b91c1c" font-size="11">slow rise: 10k x Cload</text><text x="10" y="272" fill="#1d2943" font-size="11">IN low -> FET off -> OUT pulled to 5V. IN high -> FET on -> OUT ~0V.</text><text x="10" y="292" fill="#64748b" font-size="11">Static current 5V/10k = 0.5mA while on. Fall is FET-driven, rise is resistor-only.</text></svg></div>$vsq$ as box) n
 where question like $q$%上方接 10KΩ 上拉到 5V%$q$;

-- q16：I2C Fast mode 關鍵時序
update public.interview_questions set
  answer = case when answer is not null and answer not like '%<svg%' then n.box || answer else answer end,
  answer_en = case when answer_en is not null and answer_en not like '%<svg%' then n.box || answer_en else answer_en end,
  answer_ja = case when answer_ja is not null and answer_ja not like '%<svg%' then n.box || answer_ja else answer_ja end,
  answer_ko = case when answer_ko is not null and answer_ko not like '%<svg%' then n.box || answer_ko else answer_ko end
  from (select $vsq$<div class="exam-diagram-box"><svg width="520" height="360" viewBox="0 0 520 360" xmlns="http://www.w3.org/2000/svg"><rect width="520" height="360" fill="#ffffff"/><text x="260" y="20" fill="#1d2943" font-size="13" text-anchor="middle" font-weight="bold">I2C Fast Mode: the five SCL timing checks</text><line x1="60" y1="108" x2="480" y2="108" stroke="#94a3b8" stroke-width="1" stroke-linecap="round"/><line x1="60" y1="132" x2="480" y2="132" stroke="#94a3b8" stroke-width="1" stroke-linecap="round"/><text x="486" y="112" fill="#64748b" font-size="11">70%</text><text x="486" y="136" fill="#64748b" font-size="11">30%</text><polyline points="60,150 100,150 130,90 210,90 240,150 320,150 350,90 430,90 460,150 490,150" fill="none" stroke="#1f4fd1" stroke-width="2" stroke-linejoin="round" stroke-linecap="round"/><line x1="109" y1="76" x2="121" y2="76" stroke="#b91c1c" stroke-width="1.2" stroke-linecap="round"/><line x1="109" y1="72" x2="109" y2="80" stroke="#b91c1c" stroke-width="1.2" stroke-linecap="round"/><line x1="121" y1="72" x2="121" y2="80" stroke="#b91c1c" stroke-width="1.2" stroke-linecap="round"/><text x="115" y="70" fill="#b91c1c" font-size="11" text-anchor="middle" font-weight="bold">tr</text><line x1="219" y1="76" x2="231" y2="76" stroke="#b91c1c" stroke-width="1.2" stroke-linecap="round"/><line x1="219" y1="72" x2="219" y2="80" stroke="#b91c1c" stroke-width="1.2" stroke-linecap="round"/><line x1="231" y1="72" x2="231" y2="80" stroke="#b91c1c" stroke-width="1.2" stroke-linecap="round"/><text x="225" y="70" fill="#b91c1c" font-size="11" text-anchor="middle" font-weight="bold">tf</text><line x1="121" y1="172" x2="219" y2="172" stroke="#b45309" stroke-width="1.2" stroke-linecap="round"/><line x1="121" y1="168" x2="121" y2="176" stroke="#b45309" stroke-width="1.2" stroke-linecap="round"/><line x1="219" y1="168" x2="219" y2="176" stroke="#b45309" stroke-width="1.2" stroke-linecap="round"/><text x="170" y="188" fill="#b45309" font-size="11" text-anchor="middle">tHIGH >= 0.6us</text><line x1="231" y1="172" x2="329" y2="172" stroke="#b45309" stroke-width="1.2" stroke-linecap="round"/><line x1="231" y1="168" x2="231" y2="176" stroke="#b45309" stroke-width="1.2" stroke-linecap="round"/><line x1="329" y1="168" x2="329" y2="176" stroke="#b45309" stroke-width="1.2" stroke-linecap="round"/><text x="280" y="188" fill="#b45309" font-size="11" text-anchor="middle">tLOW >= 1.3us</text><text x="10" y="226" fill="#1d2943" font-size="11">1   fSCL <= 400 kHz</text><text x="10" y="248" fill="#1d2943" font-size="11">2   tLOW >= 1.3us, tHIGH >= 0.6us</text><text x="10" y="270" fill="#b91c1c" font-size="11">3   tr 20-300ns, tf <= 300ns        <- the one that usually fails</text><text x="10" y="292" fill="#1d2943" font-size="11">4   tSU:DAT >= 100ns, tHD:DAT 0-0.9us</text><text x="10" y="314" fill="#1d2943" font-size="11">5   tHD:STA >= 0.6us, tSU:STO >= 0.6us, tBUF >= 1.3us</text><text x="10" y="342" fill="#64748b" font-size="11">All of them are measured at the 30% / 70% VDD crossings, not at the rails.</text></svg></div>$vsq$ as box) n
 where question like $q$%I2C Fast Mode 規格中%$q$;

-- q22：差分對疊構剖面（按比例）
update public.interview_questions set
  answer = case when answer is not null and answer not like '%<svg%' then n.box || answer else answer end,
  answer_en = case when answer_en is not null and answer_en not like '%<svg%' then n.box || answer_en else answer_en end,
  answer_ja = case when answer_ja is not null and answer_ja not like '%<svg%' then n.box || answer_ja else answer_ja end,
  answer_ko = case when answer_ko is not null and answer_ko not like '%<svg%' then n.box || answer_ko else answer_ko end
  from (select $vsq$<div class="exam-diagram-box"><svg width="520" height="330" viewBox="0 0 520 330" xmlns="http://www.w3.org/2000/svg"><rect width="520" height="330" fill="#ffffff"/><text x="260" y="20" fill="#1d2943" font-size="13" text-anchor="middle" font-weight="bold">Microstrip pair: from geometry to 96 ohm</text><rect x="20" y="149.6" width="300" height="32" fill="#e2e8f0" stroke="#cbd5e1" stroke-width="1"/><rect x="20" y="181.6" width="300" height="10" fill="#1f4fd1" opacity="0.85" stroke="#1f4fd1" stroke-width="1"/><rect x="60" y="140" width="40" height="9.6" fill="#1f4fd1" stroke="#1f4fd1" stroke-width="1"/><rect x="140" y="140" width="40" height="9.6" fill="#1f4fd1" stroke="#1f4fd1" stroke-width="1"/><text x="80" y="130" fill="#1d2943" font-size="11" text-anchor="middle">W 5mil</text><text x="120" y="112" fill="#1d2943" font-size="11" text-anchor="middle">S 5mil</text><text x="160" y="130" fill="#1d2943" font-size="11" text-anchor="middle">W 5mil</text><text x="80" y="169.6" fill="#64748b" font-size="11" text-anchor="middle">H 4mil</text><text x="260" y="169.6" fill="#64748b" font-size="11" text-anchor="middle">er 4.2</text><text x="190" y="207.6" fill="#64748b" font-size="11" text-anchor="middle">solid GND plane</text><text x="330" y="146" fill="#1d2943" font-size="11">T 1.2mil</text><text x="10" y="238" fill="#1d2943" font-size="11">Z0 = 87/sqrt(er+1.41) x ln(5.98H / (0.8W+T)) = 36.7 x ln(4.6) = 56 ohm</text><text x="10" y="260" fill="#1d2943" font-size="11">Zdiff = 2 x Z0 x (1 - 0.48 x exp(-0.96 S/H)) = 112 x 0.855 = 96 ohm</text><text x="10" y="292" fill="#64748b" font-size="11">USB asks for 90 ohm +/-10% (81-99), so 96 passes - but it sits on the high side.</text><text x="10" y="312" fill="#64748b" font-size="11">Widen W or tighten S to pull it back to centre, then confirm in a field solver.</text></svg></div>$vsq$ as box) n
 where question like $q$%差分阻抗設計%$q$;

-- 驗收：七列的 zh / en 都要 t
select left(question, 22) as q,
       answer like '%<svg%' as zh, answer_en like '%<svg%' as en,
       answer_ja like '%<svg%' as ja, answer_ko like '%<svg%' as ko
  from public.interview_questions
 where question like $q$%BJT (NPN) 的飽和%$q$
    or question like $q$%NMOSFET 的開啟%$q$
    or question like $q$%BJT 的四種工作區域%$q$
    or question like $q$%請填寫以下邏輯閘的真值表%$q$
    or question like $q$%上方接 10KΩ 上拉到 5V%$q$
    or question like $q$%I2C Fast Mode 規格中%$q$
    or question like $q$%差分阻抗設計%$q$;
